"""Generate wordstat/formats.py from data/formats.csv.

Run from the repository root: python tools/gen_formats.py
"""

import csv
from pathlib import Path

SOURCE = Path("data/formats.csv")
TARGET = Path("wordstat/formats.py")


def main() -> None:
    with SOURCE.open(newline="", encoding="utf-8") as f:
        rows = list(csv.DictReader(f))

    lines = [
        "# Code generated by tools/gen_formats.py from data/formats.csv. DO NOT EDIT.",
        "",
        "import enum",
        "",
        "",
        "class Format(enum.Enum):",
    ]
    lines += [f'    {r["name"].upper()} = "{r["name"]}"' for r in rows]
    lines += ["", "", "DESCRIPTIONS = {"]
    lines += [f'    Format.{r["name"].upper()}: "{r["description"]}",' for r in rows]
    lines += ["}", ""]
    TARGET.write_text("\n".join(lines), encoding="utf-8")


if __name__ == "__main__":
    main()
